    rows = [row[:] for row in grid]
    h, w = len(rows), len(rows[0])
    counts = {}
    for row in rows:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)

    for r in range(h):
        positions = [c for c, value in enumerate(grid[r]) if value != background]
        if positions:
            for c in range(min(positions), max(positions) + 1):
                if grid[r][c] == background:
                    rows[r][c] = 2

    for c in range(w):
        positions = [r for r in range(h) if grid[r][c] != background]
        if positions:
            for r in range(min(positions), max(positions) + 1):
                if grid[r][c] == background:
                    rows[r][c] = 2
    return rows
'''
